#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; cin>>n;
    vector<int> ks(n);
    vector<vector<pair<int,int>>> orig(n);
    int totalCells=0;
    for(int i=0;i<n;i++){
        cin>>ks[i]; orig[i].resize(ks[i]);
        for(int j=0;j<ks[i];j++) cin>>orig[i][j].first>>orig[i][j].second;
        totalCells+=ks[i];
    }
    // Transform: rotate r times 90° CCW, then if f=1 flip x -> -x
    auto transform=[&](const vector<pair<int,int>>&cells,int r,int f)->vector<pair<int,int>>{
        vector<pair<int,int>> res;
        for(auto[x,y]:cells){
            int nx=x,ny=y;
            for(int q=0;q<r;q++){int t=-ny;ny=nx;nx=t;}
            if(f) nx=-nx;
            res.push_back({nx,ny});
        }
        int mx=INT_MAX,my=INT_MAX;
        for(auto[x,y]:res){mx=min(mx,x);my=min(my,y);}
        for(auto&[x,y]:res){x-=mx;y-=my;}
        return res;
    };
    struct Ori{vector<pair<int,int>>cells;int w,h,r,f;};
    vector<vector<Ori>> allOris(n);
    for(int i=0;i<n;i++){
        set<vector<pair<int,int>>>seen;
        for(int f=0;f<2;f++) for(int r=0;r<4;r++){
            auto tc=transform(orig[i],r,f);
            sort(tc.begin(),tc.end());
            if(seen.insert(tc).second){
                int w=0,h=0;
                for(auto[x,y]:tc){w=max(w,x+1);h=max(h,y+1);}
                allOris[i].push_back({tc,w,h,r,f});
            }
        }
    }
    vector<int> order(n);
    iota(order.begin(),order.end(),0);
    sort(order.begin(),order.end(),[&](int a,int b){return ks[a]>ks[b];});
    int bestArea=INT_MAX,bestW=0,bestH=0;
    struct Pl{int x,y,r,f;};
    vector<Pl> bestPl(n);
    auto st=chrono::steady_clock::now();
    auto el=[&](){return chrono::duration<double>(chrono::steady_clock::now()-st).count();};
    double sq=sqrt((double)totalCells);
    int lo=max(1,(int)(sq*0.3)),hi=min((int)(sq*4)+20,totalCells+10);
    for(int W=lo;W<=hi&&el()<9.0;W++){
        int maxH=totalCells+10;
        if((long long)W>bestArea)continue;
        vector<int>hmap(W,0);
        vector<vector<bool>>grid(W,vector<bool>(maxH,false));
        vector<Pl>pl(n);int curH=0;bool fail=false;
        for(int idx=0;idx<n;idx++){
            int pi=order[idx];int bs=INT_MAX,bx=-1,by=-1,boi=-1;
            for(int oi=0;oi<(int)allOris[pi].size();oi++){
                auto&o=allOris[pi][oi];
                if(o.w>W)continue;
                for(int x=0;x<=W-o.w;x++){
                    int my=0;
                    for(auto&[cx,cy]:o.cells)my=max(my,hmap[x+cx]-cy);
                    if(my<0)my=0;
                    int top=0;
                    for(auto&[cx,cy]:o.cells)top=max(top,my+cy+1);
                    if(top>=maxH)continue;
                    bool ok=true;
                    for(auto&[cx,cy]:o.cells)if(grid[x+cx][my+cy]){ok=false;break;}
                    if(ok){int s=top;if(s<bs){bs=s;bx=x;by=my;boi=oi;}}
                }
            }
            if(bx<0){fail=true;break;}
            auto&o=allOris[pi][boi];
            for(auto&[cx,cy]:o.cells){grid[bx+cx][by+cy]=true;hmap[bx+cx]=max(hmap[bx+cx],by+cy+1);curH=max(curH,by+cy+1);}
            pl[pi]={bx,by,o.r,o.f};
        }
        if(fail)continue;
        int area=W*curH;
        if(area<bestArea){bestArea=area;bestW=W;bestH=curH;bestPl=pl;}
    }
    if(bestArea==INT_MAX){bestW=totalCells;bestH=1;int cx=0;for(int i=0;i<n;i++){bestPl[i]={cx,0,0,0};cx+=ks[i];}bestW=cx;}
    cout<<bestW<<" "<<bestH<<"\n";
    for(int i=0;i<n;i++) cout<<bestPl[i].x<<" "<<bestPl[i].y<<" "<<bestPl[i].r<<" "<<bestPl[i].f<<"\n";
}
